// Renders every Seramet print template at 58mm, 80mm and A4 into
// docs/print-previews/ so layouts can be reviewed without a printer.
//   npx vite-node scripts/render-print-previews.ts
import { mkdirSync, writeFileSync } from "node:fs";
import { join } from "node:path";
import { renderAllSamples } from "../src/printing/documents/samples";

const outDir = join(process.cwd(), "docs", "print-previews");
mkdirSync(outDir, { recursive: true });

const index: string[] = [
  "# Print template previews",
  "",
  "Generated by `scripts/render-print-previews.ts`.",
  "",
];
for (const paper of ["58mm", "80mm", "A4"] as const) {
  for (const document of renderAllSamples(paper)) {
    const name = `${document.kind.toLowerCase().replace(/_/g, "-")}-${paper.toLowerCase()}.txt`;
    const qr = document.qrCodes.map((q) => `\n[QR ${q.purpose}: ${q.caption}]`).join("");
    writeFileSync(join(outDir, name), `${document.content}${qr}\n`);
    const lines = document.content.split("\n").length;
    index.push(`- [${document.kind} ${paper}](./${name}) - ${lines} lines`);
  }
}
writeFileSync(join(outDir, "README.md"), `${index.join("\n")}\n`);
console.log(`Wrote ${index.length - 4} previews to ${outDir}`);
